#include<bits/stdc++.h>
using namespace std;

int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }

    vector<int>leaves;
    for(int i=1;i<=N;i++) if(ch[i].empty()) leaves.push_back(i);

    int K=0;
    vector<vector<int>>bags; // 0-indexed internally
    vector<pair<int,int>>edges;
    bags.push_back({}); // placeholder for 1-indexing
    K=0;

    auto newBag=[&](vector<int> b)->int{
        K++;
        bags.push_back(b);
        return K;
    };

    // For each node, store the bag id that "represents" it (contains it and its parent)
    // and the leftmost and rightmost leaf in its subtree
    vector<int>repBag(N+1,0), leftLeaf(N+1,0), rightLeaf(N+1,0);

    // Process bottom-up (reverse order since numbering is preorder)
    for(int v=N;v>=1;v--){
        if(ch[v].empty()){
            // Leaf node
            leftLeaf[v]=v;
            rightLeaf[v]=v;
            // Create a bag {par[v], v} - will be extended later or used as anchor
            if(par[v]){
                int b=newBag({par[v],v});
                repBag[v]=b;
            } else {
                int b=newBag({v});
                repBag[v]=b;
            }
        } else {
            // Internal node with children c1,...,ck
            auto &C=ch[v];
            int k=C.size();
            leftLeaf[v]=leftLeaf[C[0]];
            rightLeaf[v]=rightLeaf[C[k-1]];

            // Create chain of bags for v
            // First bag includes par[v](if exists), v, C[0]
            // Then for consecutive children pairs, create bags {v, ci, ci+1} or {par[v],v,ci,ci+1}
            // Also need to handle ring edges between rightLeaf[ci] and leftLeaf[ci+1]

            int prevBagId=0;
            for(int i=0;i<k;i++){
                vector<int>bag;
                if(par[v]) bag.push_back(par[v]);
                bag.push_back(v);
                bag.push_back(C[i]);
                if(i+1<k){
                    // Ring edge: rightLeaf[C[i]] -- leftLeaf[C[i+1]]
                    // Add both to cover ring edge
                    int rl=rightLeaf[C[i]], ll=leftLeaf[C[i+1]];
                    bag.push_back(rl);
                    int b1=newBag(bag);
                    if(prevBagId) edges.push_back({prevBagId,b1});
                    edges.push_back({repBag[C[i]],b1});
                    // bag with ring edge
                    vector<int>bag2;
                    if(par[v]) bag2.push_back(par[v]);
                    bag2.push_back(v);
                    bag2.push_back(ll);
                    bag2.push_back(rl);
                    int b2=newBag(bag2);
                    edges.push_back({b1,b2});
                    prevBagId=b2;
                } else {
                    int b1=newBag(bag);
                    if(prevBagId) edges.push_back({prevBagId,b1});
                    edges.push_back({repBag[C[i]],b1});
                    prevBagId=b1;
                }
            }
            repBag[v]=prevBagId;
        }
    }
    // Handle ring edge between last leaf and first leaf
    if(leaves.size()>=2){
        int rl=rightLeaf[1], ll=leftLeaf[1];
        // Ring edge: leaves.back() -- leaves.front(), i.e., rightLeaf[1]--leftLeaf[1]
        // Actually ring is v1-v2-...-vk-v1 where vi are leaves in order
        // Last ring edge: leaves.back() to leaves.front()
        vector<int>bag={1,leaves.back(),leaves.front()};
        int b=newBag(bag);
        edges.push_back({repBag[1],b});
    }

    printf("%d\n",K);
    for(int i=1;i<=K;i++){
        printf("%d",(int)bags[i].size());
        for(int x:bags[i]) printf(" %d",x);
        printf("\n");
    }
    for(auto&[a,b]:edges) printf("%d %d\n",a,b);
    return 0;
}
